# El contorno real de cada logotipo (x, y, ancho, alto) sobre su cuadrícula de 24, medido dibujándolos. Con él, todos
# se ven del mismo tamaño: cada uno ocupa la misma superficie que uno cuadrado que llena su recuadro (la bola del
# mundo dejaba 2 de margen por lado; el velero de phpMyAdmin, apaisado, se veía más pequeño). Los apaisados o
# alargados se salen por su lado largo, como mucho LOGO_OVER. Uno sin medir, la cuadrícula entera
LOGO_BOX = {"actualizar": (1.25, 1.25, 21.5, 21.5), "apache": (5.2, 0, 13.6, 24), "bbdd": (3.5, 4, 17, 16), "cloudflare": (0, 6.6, 24, 10.85), "descarga": (4, 3, 16, 18.6), "docker": (0, 3.4, 24, 17.25), "github": (0, 0.3, 24, 23.4), "globo": (2, 2, 20, 20), "imagenes": (1.25, 1.25, 21.5, 21.5), "log": (2, 1, 20, 22), "mailpit": (0, 0.95, 24, 22.1), "mariadb": (0.05, 4.25, 23.95, 15.5), "node": (3.35, 2.2, 17.35, 19.6), "nginx": (3.35, 2.2, 17.35, 19.6), "perl": (2.65, 0, 18.7, 24), "php": (0, 5.7, 24, 12.65), "phpmyadmin": (0.05, 3.5, 23.9, 17.05), "prestashop": (0, 1.05, 24, 21.95), "wordpress": (0, 0, 24, 24), "xampp": (0.1, 0, 23.8, 24)}
LOGO_OVER = 1.2
# Los que se dibujan con trazo, no rellenos
LOGO_STROKED = {"imagenes"}
_logo_cache = {}


def dark_theme():
    """¿El tema es oscuro? (por el color de fondo de las ventanas)"""
    if "dark" not in _logo_cache:
        ctx = Gtk.Window().get_style_context()
        found, bg = ctx.lookup_color("theme_bg_color")
        _logo_cache["dark"] = found and (0.299 * bg.red + 0.587 * bg.green + 0.114 * bg.blue) < 0.5
    return _logo_cache["dark"]


def logo_frame(name, size):
    """(ancho, alto) de la imagen de un logotipo de tamaño size y su viewBox: el lado corto, size; el largo, hasta
    size * LOGO_OVER, para que todos ocupen la misma superficie (logotipos.LOGO_BOX)."""
    x, y, w, h = LOGO_BOX.get(name, (0, 0, 24, 24))
    extra = min(LOGO_OVER, (max(w, h) / max(0.1, min(w, h))) ** 0.5)
    side = max(w, h) / extra
    cx, cy = x + w / 2, y + h / 2
    if w >= h:
        return int(round(size * extra)), size, "%g %g %g %g" % (x, cy - side / 2, w, side)
    return size, int(round(size * extra)), "%g %g %g %g" % (cx - side / 2, y, side, h)


def logo_pixbuf(name, size, scale, color=None):
    """Imagen del logotipo de un paquete a esa escala, en su color o en el que se indique."""
    key = (name, size, scale, color)
    if key not in _logo_cache:
        color = color or LOGO_COLORS[name][1 if dark_theme() else 0]
        paint = ('fill="none" stroke="%s" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"'
                 if name in LOGO_STROKED else 'fill="%s"') % color
        paths = '<path %s d="%s"/>' % (paint, LOGO_PATHS[name])
        # (en sus colores, por partes; con un color pedido, en ese, entero)
        if key[3] is None and name in LOGO_PARTS:
            paths = "".join('<path fill="%s" d="%s"/>' % (c[1 if dark_theme() else 0], d) for d, c in LOGO_PARTS[name])
        w, h, box = logo_frame(name, size * scale)
        svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="%s" width="%d" height="%d">%s</svg>'
               % (box, w, h, paths))
        loader = GdkPixbuf.PixbufLoader.new_with_type("svg")
        loader.write(svg.encode())
        loader.close()
        _logo_cache[key] = loader.get_pixbuf()
    return _logo_cache[key]


def logo(name, size=18):
    """Logotipo de un paquete en su color, nítido también en pantallas con escala 2."""
    scale = max(1, Gdk.Display.get_default().get_monitor(0).get_scale_factor())
    img = Gtk.Image()
    img.set_from_surface(Gdk.cairo_surface_create_from_pixbuf(logo_pixbuf(name, size, scale), scale, None))
    return img


# Logotipos con su tipografía (Apariencia): los oficiales de Docker (docker.com), Node.js (nodejs.org; con
# letra oscura en el tema claro y clara en el oscuro) y PHP (php.net), en SVG comprimido
BRAND_SVG = {
    "docker": "",
    "node-claro": "",
    "node-oscuro": "",
    "php": "",
}
BRAND_RATIO = {"docker": 4.6642, "node-claro": 3.3375, "node-oscuro": 3.3375, "php": 1.854}
_brand_cache = {}


def brand_pixbuf(key, height, scale):
    k = (key, height, scale)
    if k not in _brand_cache:
        loader = GdkPixbuf.PixbufLoader.new_with_type("svg")
        h = height * scale
        loader.set_size(int(round(h * BRAND_RATIO[key])), h)
        loader.write(zlib.decompress(base64.b64decode(BRAND_SVG[key])))
        loader.close()
        _brand_cache[k] = loader.get_pixbuf()
    return _brand_cache[k]


def row_selected(widget):
    """¿Va en la fila elegida de una lista? (GTK no les pasa ese estado a los dibujos de dentro)"""
    row = widget.get_ancestor(Gtk.ListBoxRow)
    return row is not None and row.is_selected()


class BrandLogo(Gtk.DrawingArea):
    """El logotipo de Docker, Node o PHP con su tipografía. De un color (mono, o en la fila elegida) se
    pinta con el del texto; PHP, siempre en el suyo (de un color su óvalo taparía las letras)."""

    def __init__(self, name, height, mono=False):
        super().__init__()
        self.name, self.height, self.mono = name, height, mono
        key = "node-claro" if name == "node" else name
        self.set_size_request(int(round(height * BRAND_RATIO[key])), height)
        self.set_valign(Gtk.Align.CENTER)

    def do_draw(self, cr):
        scale = max(1, self.get_scale_factor())
        key = ("node-oscuro" if dark_theme() else "node-claro") if self.name == "node" else self.name
        pix = brand_pixbuf(key, self.height, scale)
        y = (self.get_allocated_height() * scale - pix.get_height()) / 2
        cr.save()
        cr.scale(1.0 / scale, 1.0 / scale)
        if self.name != "php" and (self.mono or row_selected(self)):
            c = self.get_style_context().get_color(self.get_state_flags())
            cr.set_source_rgba(c.red, c.green, c.blue, c.alpha)
            cr.mask_surface(Gdk.cairo_surface_create_from_pixbuf(pix, 1, None), 0, y)
        else:
            Gdk.cairo_set_source_pixbuf(cr, pix, 0, y)
            cr.paint()
        cr.restore()
        return False


# Parches nuevos dejados para luego («Ahora no»): la lista de entonces; el aviso vuelve si cambia
IGNORED_UPDATES_FILE = os.path.join(LOG_DIR, "parches-para-luego")
_ignored_sim = []


def updates_ignored(items):
    if _ignored_sim:
        return _ignored_sim[0] == "\n".join(sorted(items))
    try:
        with open(IGNORED_UPDATES_FILE, encoding="utf-8") as fh:
            return fh.read(20000) == "\n".join(sorted(items))
    except OSError:
        return False


def updates_ignore(items):
    text = "\n".join(sorted(items))
    if SIMULATE:
        _ignored_sim[:] = [text]
        return
    os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
    with open(IGNORED_UPDATES_FILE + ".nuevo", "w", encoding="utf-8") as fh:
        fh.write(text)
    os.replace(IGNORED_UPDATES_FILE + ".nuevo", IGNORED_UPDATES_FILE)


# Menú lateral: sus apartados (clave, texto e icono) y cómo se ven (Apariencia: ~/.nexum/apariencia)
SIDEBAR = [("ENTORNO", [("proyectos", "Proyectos", "folder-symbolic"), ("repos", "Repositorios", "logo:github"),
                        ("versiones", "Versiones de PHP", "logo:php"), ("bbdd", "Bases de datos", "logo:bbdd"),
                        ("docker", "Docker", "logo:docker"), ("node", "Node", "logo:node"),
                        ("nginx", "Nginx", "logo:nginx")]),
           ("SISTEMA", [("dominios", "Dominios y hosts", "network-workgroup-symbolic"),
                        ("config", "Configuración", "emblem-system-symbolic")])]
# (siempre se ven: sin Configuración no se podrían volver a enseñar)
SIDEBAR_FIXED = ("proyectos", "config")


def nginx_used():
    """Nginx, apagado de serie: su pestaña solo sale encendido (Configuración, Nginx: nginx-usar si)."""
    return os.path.exists(os.path.join(LOG_DIR, "nginx", "usar"))
LOOK_FILE = os.path.join(LOG_DIR, "apariencia")
_look_sim = {}


def look_conf():
    """color (iconos en color), marcas (Docker, Node y PHP con su logotipo), ocultos (apartados que no se ven),
    zoom (el tamaño de la ventana, en %) y cristal (paneles translúcidos sobre un fondo de color)."""
    conf = dict(_look_sim)
    if not conf:
        try:
            with open(LOOK_FILE, encoding="utf-8") as fh:
                conf = json.loads(fh.read(4000))
        except (OSError, ValueError):
            conf = {}
    if not isinstance(conf, dict):
        conf = {}
    keys = {k for _g, items in SIDEBAR for k, _t, _i in items} - set(SIDEBAR_FIXED)
    hidden = conf.get("ocultos")
    return {"color": conf.get("color") is True, "marcas": conf.get("marcas") is True,
            "ocultos": {k for k in hidden if k in keys} if isinstance(hidden, list) else set(),
            "zoom": conf.get("zoom") if conf.get("zoom") in LOOK_ZOOMS else 100, "cristal": conf.get("cristal") is True}


# Tamaño de la ventana (Apariencia): en tanto por ciento
LOOK_ZOOMS = (80, 90, 100, 110)


def look_save(conf):
    data = {"color": conf["color"], "marcas": conf["marcas"], "ocultos": sorted(conf["ocultos"]),
            "zoom": conf.get("zoom", 100), "cristal": conf.get("cristal") is True}
    if SIMULATE:
        _look_sim.clear()
        _look_sim.update(data)
        return
    os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
    with open(LOOK_FILE + ".nuevo", "w", encoding="utf-8") as fh:
        json.dump(data, fh)
    os.replace(LOOK_FILE + ".nuevo", LOOK_FILE)


def css_zoom(text, zoom):
    """La hoja de estilos a otro tamaño: cada medida en px por zoom (las de 1 px, las rayas, se quedan igual).
    Las letras no van aquí: crecen o menguan con la resolución (gtk-xft-dpi), y con ellas las medidas en em."""
    if zoom == 100:
        return text

    def one(m):
        v = float(m.group(1))
        return m.group(0) if v <= 1 else "%gpx" % max(1, round(v * zoom / 100.0))
    return re.sub(r"(?<![\w.#-])(\d+(?:\.\d+)?)px", one, text)


GLASS_DIR = os.path.join(LOG_DIR, "cache", "cristal")


def glass_css():
    """El fondo del cristal: tres manchas difuminadas (azul, violeta y verde, los colores de Nexum) pintadas una
    sola vez en una imagen pequeña (~/.nexum/cache/cristal), que GTK estira a la ventana. Con degradados de CSS,
    GTK los volvía a calcular entero cada vez que se redibujaba algo (unos 28 ms; estirando la imagen, menos de 1)."""
    import cairo
    w, h = 256, 176
    out = []
    for name, sel, base, alpha in (("oscuro", "window.background.nv-cristal", (0.15, 0.16, 0.18), 1.0),
                                   ("claro", "window.background.nv-cristal.nv-claro", (0.95, 0.95, 0.96), 0.6)):
        path = os.path.join(GLASS_DIR, "fondo-%s.png" % name)
        if not os.path.isfile(path):
            try:
                os.makedirs(GLASS_DIR, mode=0o700, exist_ok=True)
                surf = cairo.ImageSurface(cairo.FORMAT_RGB24, w, h)
                cr = cairo.Context(surf)
                cr.set_source_rgb(*base)
                cr.paint()
                for cx, cy, r, rgb, a in ((0.08 * w, 0, 0.9, (0.11, 0.39, 0.93), 0.38),
                                          (w, h, 0.9, (0.49, 0.44, 0.85), 0.34),
                                          (0.62 * w, 0.3 * h, 0.6, (0.11, 0.61, 0.42), 0.16)):
                    g = cairo.RadialGradient(cx, cy, 0, cx, cy, r * max(w, h))
                    g.add_color_stop_rgba(0, rgb[0], rgb[1], rgb[2], a * alpha)
                    g.add_color_stop_rgba(1, rgb[0], rgb[1], rgb[2], 0)
                    cr.set_source(g)
                    cr.paint()
                surf.write_to_png(path + ".nuevo")
                os.replace(path + ".nuevo", path)
            except (OSError, MemoryError, cairo.Error):
                continue
        out.append('%s { background-color: rgb(%d, %d, %d); background-image: url("%s"); background-size: 100%% 100%%; }'
                   % (sel, base[0] * 255, base[1] * 255, base[2] * 255, GLib.filename_to_uri(path, None)))
    return "\n".join(out)


class MonoLogo(Gtk.DrawingArea):
    """Logotipo de un solo color, el del texto de donde va (como los iconos simbólicos del tema): en
    la barra lateral, igual que los demás iconos, también al elegir el apartado o cambiar de tema."""

    def __init__(self, name, size=16, colored=False):
        super().__init__()
        self.name, self.size, self.colored = name, size, colored
        w, h, _box = logo_frame(name, size)
        self.set_size_request(w, h)
        self.set_valign(Gtk.Align.CENTER)

    def do_draw(self, cr):
        c = self.get_style_context().get_color(self.get_state_flags())
        color = "#%02x%02x%02x" % (int(c.red * 255), int(c.green * 255), int(c.blue * 255))
        # (en color, el suyo; en la fila elegida, el del texto, que se lea sobre el azul)
        if self.colored and not row_selected(self):
            color, c = None, Gdk.RGBA(0, 0, 0, 1)
        scale = max(1, self.get_scale_factor())
        pix = logo_pixbuf(self.name, self.size, scale, color)
        cr.save()
        cr.scale(1.0 / scale, 1.0 / scale)
        Gdk.cairo_set_source_pixbuf(cr, pix, (self.get_allocated_width() * scale - pix.get_width()) / 2,
                                    (self.get_allocated_height() * scale - pix.get_height()) / 2)
        cr.paint_with_alpha(c.alpha)
        cr.restore()
        return False


def symbol(name, size=18):
    """Icono simbólico del tema (con otro de reserva si el tema no lo tiene)."""
    if not Gtk.IconTheme.get_default().has_icon(name):
        name = "applications-system-symbolic"
    return icon(name, size)


